SELECT COUNT(*) FROM clinical c 
JOIN transplant_matching t ON c.clin_recip_registry = t.recip_ref_reg;

-- Check if admin_rev_registry links to transplant_matching
SELECT COUNT(*) FROM administrative_and_review a 
JOIN transplant_matching t ON a.adm_rev_registry = t.match_rec_registry;

